5979 bool llvm::canIgnoreSignBitOfNaN(const Use &U) {
5980   auto *User = cast<Instruction>(U.getUser());
5981   if (auto *FPOp = dyn_cast<FPMathOperator>(User)) {
5982     if (FPOp->hasNoNaNs())
5983       return true;
5984   }
5985 
5986   switch (User->getOpcode()) {
5987   case Instruction::FPToSI:
5988   case Instruction::FPToUI:
5989     return true;
5990   // Proper FP math operations ignore the sign bit of NaN.
5991   case Instruction::FAdd:
5992   case Instruction::FSub:
5993   case Instruction::FMul:
5994   case Instruction::FDiv:
5995   case Instruction::FRem:
5996   case Instruction::FPTrunc:
5997   case Instruction::FPExt:
5998   case Instruction::FCmp:
5999     return true;
6000   // Bitwise FP operations should preserve the sign bit of NaN.
6001   case Instruction::FNeg:
6002   case Instruction::Select:
6003   case Instruction::PHI:
6004     return false;
6005   case Instruction::Ret:
6006     return User->getFunction()->getAttributes().getRetNoFPClass() &
6007            FPClassTest::fcNan;
6008   case Instruction::Call:
6009   case Instruction::Invoke: {
6010     if (auto *II = dyn_cast<IntrinsicInst>(User)) {
6011       switch (II->getIntrinsicID()) {
6012       case Intrinsic::fabs:
6013         return true;
6014       case Intrinsic::copysign:
6015         return U.getOperandNo() == 0;
6016       // Other proper FP math intrinsics ignore the sign bit of NaN.
6017       case Intrinsic::maxnum:
6018       case Intrinsic::minnum:
6019       case Intrinsic::maximum:
6020       case Intrinsic::minimum:
6021       case Intrinsic::maximumnum:
6022       case Intrinsic::minimumnum:
6023       case Intrinsic::canonicalize:
6024       case Intrinsic::fma:
6025       case Intrinsic::fmuladd:
6026       case Intrinsic::sqrt:
6027       case Intrinsic::pow:
6028       case Intrinsic::powi:
6029       case Intrinsic::fptoui_sat:
6030       case Intrinsic::fptosi_sat:
6031       case Intrinsic::is_fpclass:
6032       case Intrinsic::vp_is_fpclass:
6033         return true;
6034       default:
6035         return false;
6036       }
6037     }
6038 
6039     FPClassTest NoFPClass =
6040         cast<CallBase>(User)->getParamNoFPClass(U.getOperandNo());
6041     return NoFPClass & FPClassTest::fcNan;
6042   }
