6048 Value *llvm::isBytewiseValue(Value *V, const DataLayout &DL) {
6049 
6050   // All byte-wide stores are splatable, even of arbitrary variables.
6051   if (V->getType()->isIntegerTy(8))
6052     return V;
6053 
6054   LLVMContext &Ctx = V->getContext();
6055 
6056   // Undef don't care.
6057   auto *UndefInt8 = UndefValue::get(Type::getInt8Ty(Ctx));
6058   if (isa<UndefValue>(V))
6059     return UndefInt8;
6060 
6061   // Return poison for zero-sized type.
6062   if (DL.getTypeStoreSize(V->getType()).isZero())
6063     return PoisonValue::get(Type::getInt8Ty(Ctx));
6064 
6065   Constant *C = dyn_cast<Constant>(V);
6066   if (!C) {
6067     // Conceptually, we could handle things like:
6068     //   %a = zext i8 %X to i16
6069     //   %b = shl i16 %a, 8
6070     //   %c = or i16 %a, %b
6071     // but until there is an example that actually needs this, it doesn't seem
6072     // worth worrying about.
6073     return nullptr;
6074   }
6075 
6076   // Handle 'null' ConstantArrayZero etc.
6077   if (C->isNullValue())
6078     return Constant::getNullValue(Type::getInt8Ty(Ctx));
6079 
6080   // Constant floating-point values can be handled as integer values if the
6081   // corresponding integer value is "byteable".  An important case is 0.0.
6082   if (ConstantFP *CFP = dyn_cast<ConstantFP>(C)) {
6083     Type *Ty = nullptr;
6084     if (CFP->getType()->isHalfTy())
6085       Ty = Type::getInt16Ty(Ctx);
6086     else if (CFP->getType()->isFloatTy())
6087       Ty = Type::getInt32Ty(Ctx);
6088     else if (CFP->getType()->isDoubleTy())
6089       Ty = Type::getInt64Ty(Ctx);
6090     // Don't handle long double formats, which have strange constraints.
6091     return Ty ? isBytewiseValue(ConstantExpr::getBitCast(CFP, Ty), DL)
6092               : nullptr;
6093   }
6094 
6095   // We can handle constant integers that are multiple of 8 bits.
6096   if (ConstantInt *CI = dyn_cast<ConstantInt>(C)) {
6097     if (CI->getBitWidth() % 8 == 0) {
6098       assert(CI->getBitWidth() > 8 && "8 bits should be handled above!");
6099       if (!CI->getValue().isSplat(8))
6100         return nullptr;
6101       return ConstantInt::get(Ctx, CI->getValue().trunc(8));
6102     }
6103   }
6104 
6105   if (auto *CE = dyn_cast<ConstantExpr>(C)) {
6106     if (CE->getOpcode() == Instruction::IntToPtr) {
6107       if (auto *PtrTy = dyn_cast<PointerType>(CE->getType())) {
6108         unsigned BitWidth = DL.getPointerSizeInBits(PtrTy->getAddressSpace());
6109         if (Constant *Op = ConstantFoldIntegerCast(
6110                 CE->getOperand(0), Type::getIntNTy(Ctx, BitWidth), false, DL))
6111           return isBytewiseValue(Op, DL);
6112       }
6113     }
6114   }
6115 
6116   auto Merge = [&](Value *LHS, Value *RHS) -> Value * {
6117     if (LHS == RHS)
6118       return LHS;
6119     if (!LHS || !RHS)
6120       return nullptr;
6121     if (LHS == UndefInt8)
6122       return RHS;
6123     if (RHS == UndefInt8)
6124       return LHS;
6125     return nullptr;
6126   };
6127 
6128   if (ConstantDataSequential *CA = dyn_cast<ConstantDataSequential>(C)) {
6129     Value *Val = UndefInt8;
6130     for (uint64_t I = 0, E = CA->getNumElements(); I != E; ++I)
6131       if (!(Val = Merge(Val, isBytewiseValue(CA->getElementAsConstant(I), DL))))
6132         return nullptr;
6133     return Val;
6134   }
6135 
6136   if (isa<ConstantAggregate>(C)) {
6137     Value *Val = UndefInt8;
6138     for (Value *Op : C->operands())
6139       if (!(Val = Merge(Val, isBytewiseValue(Op, DL))))
6140         return nullptr;
6141     return Val;
6142   }
6143 
6144   // Don't try to handle the handful of other constants.
6145   return nullptr;
6146 }
