6148 // This is the recursive version of BuildSubAggregate. It takes a few different
6149 // arguments. Idxs is the index within the nested struct From that we are
6150 // looking at now (which is of type IndexedType). IdxSkip is the number of
6151 // indices from Idxs that should be left out when inserting into the resulting
6152 // struct. To is the result struct built so far, new insertvalue instructions
6153 // build on that.
6154 static Value *BuildSubAggregate(Value *From, Value *To, Type *IndexedType,
6155                                 SmallVectorImpl<unsigned> &Idxs,
6156                                 unsigned IdxSkip,
6157                                 BasicBlock::iterator InsertBefore) {
6158   StructType *STy = dyn_cast<StructType>(IndexedType);
6159   if (STy) {
6160     // Save the original To argument so we can modify it
6161     Value *OrigTo = To;
6162     // General case, the type indexed by Idxs is a struct
6163     for (unsigned i = 0, e = STy->getNumElements(); i != e; ++i) {
6164       // Process each struct element recursively
6165       Idxs.push_back(i);
6166       Value *PrevTo = To;
6167       To = BuildSubAggregate(From, To, STy->getElementType(i), Idxs, IdxSkip,
6168                              InsertBefore);
6169       Idxs.pop_back();
6170       if (!To) {
6171         // Couldn't find any inserted value for this index? Cleanup
6172         while (PrevTo != OrigTo) {
6173           InsertValueInst* Del = cast<InsertValueInst>(PrevTo);
6174           PrevTo = Del->getAggregateOperand();
6175           Del->eraseFromParent();
6176         }
6177         // Stop processing elements
6178         break;
6179       }
6180     }
6181     // If we successfully found a value for each of our subaggregates
6182     if (To)
6183       return To;
6184   }
6185   // Base case, the type indexed by SourceIdxs is not a struct, or not all of
6186   // the struct's elements had a value that was inserted directly. In the latter
6187   // case, perhaps we can't determine each of the subelements individually, but
6188   // we might be able to find the complete struct somewhere.
6189 
6190   // Find the value that is at that particular spot
6191   Value *V = FindInsertedValue(From, Idxs);
6192 
6193   if (!V)
6194     return nullptr;
6195 
6196   // Insert the value in the new (sub) aggregate
6197   return InsertValueInst::Create(To, V, ArrayRef(Idxs).slice(IdxSkip), "tmp",
6198                                  InsertBefore);
6199 }
