6201 // This helper takes a nested struct and extracts a part of it (which is again a
6202 // struct) into a new value. For example, given the struct:
6203 // { a, { b, { c, d }, e } }
6204 // and the indices "1, 1" this returns
6205 // { c, d }.
6206 //
6207 // It does this by inserting an insertvalue for each element in the resulting
6208 // struct, as opposed to just inserting a single struct. This will only work if
6209 // each of the elements of the substruct are known (ie, inserted into From by an
6210 // insertvalue instruction somewhere).
6211 //
6212 // All inserted insertvalue instructions are inserted before InsertBefore
6213 static Value *BuildSubAggregate(Value *From, ArrayRef<unsigned> idx_range,
6214                                 BasicBlock::iterator InsertBefore) {
6215   Type *IndexedType = ExtractValueInst::getIndexedType(From->getType(),
6216                                                              idx_range);
6217   Value *To = PoisonValue::get(IndexedType);
6218   SmallVector<unsigned, 10> Idxs(idx_range);
6219   unsigned IdxSkip = Idxs.size();
6220 
6221   return BuildSubAggregate(From, To, IndexedType, Idxs, IdxSkip, InsertBefore);
6222 }
